stage_a_raw:
{
  "decisions": [
    {
      "decision": "precedence_gap_interpretation",
      "evidence": "\"the second operation cannot start until the first operation is completed, with a minimum gap of 1 unit of time between them\"",
      "options": [
        "s[i,1] >= s[i,0] + p + gap (gap added on top of processing time)",
        "s[i,1] >= s[i,0] + gap (gap measured from start of first operation)"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "s[i,1] >= s[i,0] + p + gap (gap added on top of processing time)"
    },
    {
      "decision": "machine_sharing_scope",
      "evidence": "\"Operations from different clients may need to be performed on the same machine, and no two operations can overlap on the same machine\"",
      "options": [
        "All operations share one machine; enforce non-overlap for every pair of distinct operations",
        "Only operations of different clients share a machine; skip non-overlap for same-client pairs"
      ],
      "plausibility": [
        0.8,
        0.2
      ],
      "majority_option": "All operations share one machine; enforce non-overlap for every pair of distinct operations"
    },
    {
      "decision": "makespan_lower_bound_form",
      "evidence": "\"The makespan must be at least as long as the completion time of every operation\"",
      "options": [
        "Cmax >= s[i,o] + p for every operation (completion time)",
        "Cmax >= s[i,o] for every operation (start time only)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "Cmax >= s[i,o] + p for every operation (completion time)"
    },
    {
      "decision": "start_time_domain",
      "evidence": "\"Start times for all operations are continuous variables\"",
      "options": [
        "NonNegativeReals",
        "Reals"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "ordering_variable_pairing",
      "evidence": "\"binary decision variables determine the order of operations on shared machines\"",
      "options": [
        "One binary y per unordered pair of distinct operations (single y, two big-M constraints)",
        "Two binaries per pair (one per direction) with separate big-M constraints"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "One binary y per unordered pair of distinct operations (single y, two big-M constraints)"
    },
    {
      "decision": "objective_quantity",
      "evidence": "\"minimize the total production time, known as the makespan, which is the time when the last operation across all clients is completed\"",
      "options": [
        "minimize Cmax (makespan variable)",
        "minimize sum of completion times"
      ],
      "plausibility": [
        0.98,
        0.02
      ],
      "majority_option": "minimize Cmax (makespan variable)"
    }
  ]
}
